`default_nettype none
`include "defines.sv"

// free input variables, can take any value each cycle as long as the `assume` are satisfied
module testbench (
	input check,
	input clock, reset
);
	`RVFI_WIRES
	`RVFI_BUS_WIRES

	`RISCV_FORMAL_CHECKER checker_inst (
		.clock  (clock),
		.reset  (reset),
		.check   (check),
		`RVFI_CONN
		`RVFI_BUS_CONN
	);

	// Ignore rvfi_order loopback, otherwise the check might be invalid.
	reg rvfi_order_loopback;
	always @(posedge clock) begin
		if (reset) begin
			rvfi_order_loopback <= 0;
		end else if (rvfi_valid && rvfi_order == {64{1'b1}}) begin
			rvfi_order_loopback <= 1;
		end
	end
	always_comb assume (!(rvfi_order_loopback && check));

	rvfi_wrapper wrapper (
		.clock (clock),
		.reset (reset),
		`RVFI_CONN
		`RVFI_BUS_CONN
	);

/// Helper Assertion Begin
	// Helper invariants to make the shadow-register checker inductive.
	// These only constrain post-reset states.
	always @(posedge clock) begin
		if (!reset) begin
			h_x0_is_zero: assert(wrapper.uut.regfile[0] == 0);
			if (checker_inst.register_written) begin
				h_shadow_matches_regfile: assert(checker_inst.register_shadow == wrapper.uut.regfile[checker_inst.register_index]);
			end else begin
				h_shadow_zero_when_unwritten: assert(checker_inst.register_shadow == 0);
			end
		end
	end

/// Helper Assertion End
endmodule

