				h_rvfi_rs1_rdata_stable_without_order: assert(rvfi_rs1_rdata == $past(rvfi_rs1_rdata));
				h_rvfi_rs2_addr_stable_without_order: assert(rvfi_rs2_addr == $past(rvfi_rs2_addr));
